// DAILY SPLIT — a daily word puzzle site.
// One split + one riddle a day, generated by Gemini, verified by code, pinned in Upstash.
// Zero dependencies. `node server.js`. Env: PORT, GEMINI_API_KEY..4,
// SPLIT_UPSTASH_REST_URL/TOKEN (or UPSTASH_REDIS_REST_URL/TOKEN), GEMINI_BASE_URL (testing).
const http = require('http');

const PORT = process.env.PORT || 8080;
const TZ = 'America/Chicago';
const GEMINI_BASE = process.env.GEMINI_BASE_URL || 'https://generativelanguage.googleapis.com';
const GEMINI_KEYS = [process.env.GEMINI_API_KEY, process.env.GEMINI_API_KEY2, process.env.GEMINI_API_KEY3, process.env.GEMINI_API_KEY4].filter(Boolean);
const GEMINI_MODELS = ['gemini-3.6-flash', 'gemini-3.8-flash', 'gemini-3.5-flash', 'gemini-3.5-flash-lite', 'gemini-flash-latest', 'gemini-flash-lite-latest'];
const STORE_URL = process.env.SPLIT_UPSTASH_REST_URL || process.env.UPSTASH_REDIS_REST_URL || '';
const STORE_TOKEN = process.env.SPLIT_UPSTASH_REST_TOKEN || process.env.UPSTASH_REDIS_REST_TOKEN || '';
const STORE_ON = !!(STORE_URL && STORE_TOKEN);

// ---------- hand-written, hand-verified bank (fallback + bootstrap) ----------
// Every split is letter-exact: word === first + second.
const SPLIT_BANK = [
  { word: 'therapist', pairs: [['the', 'rapist']], clue: 'A professional who listens to your problems and helps you work through them.', why: 'THERAPIST breaks into THE + RAPIST. Same letters, completely different appointment. It is the split that started this whole site.' },
  { word: 'manslaughter', pairs: [['man', 'slaughter']], clue: 'The legal charge for killing someone without meaning to.', why: 'MANSLAUGHTER is MAN + SLAUGHTER hiding in a trench coat. The law said it by accident.' },
  { word: 'carpet', pairs: [['car', 'pet']], clue: 'The soft flooring your vacuum has a personal vendetta against.', why: 'CARPET = CAR + PET. A vehicle and an animal, flattened into a rug.' },
  { word: 'nowhere', pairs: [['now', 'here'], ['no', 'where']], clue: 'Where you end up when the GPS gives up on you.', why: 'NOWHERE is both NOW + HERE and NO + WHERE at the same time. It is nowhere and now here. English is showing off.' },
  { word: 'peanut', pairs: [['pea', 'nut']], clue: 'A legume that starts bar fights in allergy forums.', why: 'PEANUT = PEA + NUT. Two foods in a trench coat pretending to be a third food.' },
  { word: 'butterfly', pairs: [['butter', 'fly']], clue: 'A garden insect that used to be a caterpillar with big dreams.', why: 'BUTTERFLY = BUTTER + FLY. Dairy plus a pest. Somehow it became the prettiest bug.' },
  { word: 'midnight', pairs: [['mid', 'night']], clue: 'Twelve o\u2019clock, when the day flips and the snacks call.', why: 'MIDNIGHT = MID + NIGHT. Nothing sinister — just the exact middle of the night, hiding in plain sight.' },
  { word: 'weekend', pairs: [['week', 'end']], clue: 'Saturday and Sunday, the two days everybody is training for.', why: 'WEEKEND = WEEK + END. The week literally ends inside the word. You earned it.' },
  { word: 'cupcake', pairs: [['cup', 'cake']], clue: 'A tiny cake that commits to one serving and one serving only.', why: 'CUPCAKE = CUP + CAKE. The rare split that describes itself perfectly.' },
  { word: 'starfish', pairs: [['star', 'fish']], clue: 'A five-armed sea creature that is somehow neither of its two words.', why: 'STARFISH = STAR + FISH. Not a star. Not a fish. A liar, technically.' },
];
const RIDDLE_BANK = [
  { riddle: 'I speak without a mouth and hear without ears. I have no body, but I come alive with wind. What am I?', answer: 'echo', aliases: ['echo', 'an echo'], hint: 'Shout into a canyon and it answers back.' },
  { riddle: 'The more of me you take, the more you leave behind. What am I?', answer: 'footsteps', aliases: ['footsteps', 'steps', 'footstep'], hint: 'You are making them right now, everywhere you go.' },
  { riddle: 'I have keys but I open no locks. I have space but no room. You can enter, but you cannot go outside. What am I?', answer: 'keyboard', aliases: ['keyboard', 'a keyboard'], hint: 'You are probably touching one today.' },
  { riddle: 'What runs but never walks, has a mouth but never talks, has a bed but never sleeps?', answer: 'river', aliases: ['river', 'a river'], hint: 'It flows right past the campsite.' },
];

// ---------- tiny Upstash REST store ----------
async function storeCmd(cmds, timeoutMs) {
  if (!STORE_ON) return null;
  try {
    const r = await fetch(STORE_URL + '/pipeline', { method: 'POST', headers: { authorization: 'Bearer ' + STORE_TOKEN, 'content-type': 'application/json' }, body: JSON.stringify(cmds), signal: timeoutMs ? AbortSignal.timeout(timeoutMs) : undefined });
    if (!r.ok) return null;
    const j = await r.json();
    return Array.isArray(j) ? j.map((x) => x && x.result) : null;
  } catch (e) { return null; }
}
const memPins = new Map();
async function pinGet(key) {
  if (memPins.has(key)) return memPins.get(key);
  const r = await storeCmd([['GET', key]], 6000);
  if (r && r[0]) { try { const v = JSON.parse(r[0]); memPins.set(key, v); return v; } catch (e) {} }
  return null;
}
async function pinSet(key, val) {
  memPins.set(key, val);
  storeCmd([['SET', key, JSON.stringify(val)]]);
}

// ---------- dates (site runs on Chicago time) ----------
function dateStr(d) {
  return new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(d);
}
function todayStr() { return dateStr(new Date()); }
function shiftDate(ds, days) {
  const d = new Date(ds + 'T12:00:00Z');
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}
function dayNumber(ds) { return Math.floor(Date.parse(ds + 'T12:00:00Z') / 86400000); }
function prettyDate(ds) {
  return new Date(ds + 'T12:00:00Z').toLocaleDateString('en-US', { timeZone: 'UTC', weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });
}

// ---------- Gemini ----------
async function askGemini(messages, maxTokens) {
  if (!GEMINI_KEYS.length) return null;
  for (const model of GEMINI_MODELS) {
    for (const key of GEMINI_KEYS) {
      try {
        const r = await fetch(GEMINI_BASE + '/v1beta/models/' + model + ':generateContent', {
          method: 'POST',
          headers: { 'content-type': 'application/json', 'x-goog-api-key': key },
          body: JSON.stringify({
            contents: messages.map((m) => ({ role: m.role === 'assistant' ? 'model' : 'user', parts: [{ text: m.content }] })),
            systemInstruction: messages.find((m) => m.role === 'system') ? { parts: [{ text: messages.find((m) => m.role === 'system').content }] } : undefined,
            generationConfig: { maxOutputTokens: maxTokens || 1200, temperature: 0.9 },
          }),
          signal: AbortSignal.timeout(45000),
        });
        if (!r.ok) continue;
        const j = await r.json();
        const text = j && j.candidates && j.candidates[0] && j.candidates[0].content && j.candidates[0].content.parts ? j.candidates[0].content.parts.map((p) => p.text || '').join('') : '';
        if (text) return text;
      } catch (e) { /* next */ }
    }
  }
  return null;
}
function parseJsonLoose(text) {
  if (!text) return null;
  const a = text.indexOf('{'); const b = text.lastIndexOf('}');
  if (a < 0 || b <= a) return null;
  try { return JSON.parse(text.slice(a, b + 1)); } catch (e) { return null; }
}
const alpha = (s) => String(s || '').toLowerCase().replace(/[^a-z]/g, '');

// ---------- verification: Gemini proposes, code decides ----------
function verifySplit(o) {
  if (!o) return null;
  const word = alpha(o.word);
  const first = alpha(o.first); const second = alpha(o.second);
  const clue = String(o.clue || '').trim(); const why = String(o.why || '').trim();
  if (!word || word.length < 5 || word.length > 14) return null;
  if (first.length < 2 || second.length < 2) return null;
  if (first + second !== word) return null; // THE LAW: letters must be exact
  if (clue.length < 12 || clue.length > 200) return null;
  if (why.length < 20 || why.length > 320) return null;
  if (clue.toLowerCase().includes(first) && clue.toLowerCase().includes(second)) return null;
  return { word, pairs: [[first, second]], clue, why, src: 'gemini' };
}
function verifyRiddle(o) {
  if (!o) return null;
  const riddle = String(o.riddle || '').trim();
  const answer = alpha(o.answer);
  const hint = String(o.hint || '').trim();
  if (riddle.length < 25 || riddle.length > 300) return null;
  if (!answer || answer.length < 3 || answer.length > 12) return null;
  if (riddle.toLowerCase().includes(answer)) return null; // answer hiding inside the riddle text = broken
  const aliases = Array.isArray(o.aliases) ? o.aliases.map(alpha).filter((a) => a && a.length <= 14) : [];
  if (!aliases.includes(answer)) aliases.push(answer);
  return { riddle, answer, aliases, hint: hint.slice(0, 140) || 'Think simpler.', src: 'gemini' };
}

const SPLIT_SYS = 'You invent word-split puzzles for a daily game. A split is ONE innocent English word whose letters break into TWO smaller real words with a funny or shocking twist (example: therapist = the + rapist). Reply with ONLY a JSON object: {"word":"...","first":"...","second":"...","clue":"a straight definition of the big word that never uses the two small words","why":"one or two funny sentences explaining the split"}. Hard rules: first+second must spell the word EXACTLY, letter for letter. Both small words must be real common English words of 2+ letters. The big word must be a real common word of 5-14 letters. Keep it clever, keep it clean enough for a general audience.';
const RIDDLE_SYS = 'You write short riddles for a daily game. Reply with ONLY a JSON object: {"riddle":"...","answer":"one common english word, 3-12 letters","aliases":["the answer plus up to 2 natural variants like a plural or with a/an"],"hint":"one short nudge that never contains the answer"}. The riddle must have ONE clear answer, must not contain the answer word anywhere in the riddle text, and should take a smart person 30-90 seconds. Fresh angle, no coffin-and-egg clichés unless twisted.';

// ---------- daily puzzle resolution: pinned gemini > pinned bank > bank ----------
const genLocks = new Set();
async function awaitPin(key, ms) {
  const t0 = Date.now();
  while (Date.now() - t0 < ms) {
    const p = await pinGet(key);
    if (p) return p;
    await new Promise((r) => setTimeout(r, 400));
  }
  return pinGet(key);
}
async function resolveDaily(kind, ds) {
  const key = 'puz:' + kind + ':' + ds;
  const pinned = await pinGet(key);
  if (pinned) return pinned;
  const bankArr = kind === 'split' ? SPLIT_BANK : RIDDLE_BANK;
  const bank = Object.assign({}, bankArr[((dayNumber(ds) % bankArr.length) + bankArr.length) % bankArr.length], { src: 'bank' });
  if (!genLocks.has(key)) {
    genLocks.add(key);
    (async () => {
      try {
        for (let i = 0; i < 4; i++) {
          const raw = kind === 'split'
            ? await askGemini([{ role: 'system', content: SPLIT_SYS }, { role: 'user', content: 'Invent today\u2019s split. Today is ' + ds + ', attempt ' + (i + 1) + ' — make it different from: therapist, manslaughter, carpet, nowhere, peanut.' }], 700)
            : await askGemini([{ role: 'system', content: RIDDLE_SYS }, { role: 'user', content: 'Write today\u2019s riddle. Today is ' + ds + ', attempt ' + (i + 1) + '.' }], 700);
          const v = kind === 'split' ? verifySplit(parseJsonLoose(raw)) : verifyRiddle(parseJsonLoose(raw));
          if (v) { await pinSet(key, v); return; }
        }
        await pinSet(key, bank);
      } catch (e) { try { await pinSet(key, bank); } catch (e2) {} }
      finally { genLocks.delete(key); }
    })();
  }
  // give generation a short head start; if it lands, everyone gets the fresh one,
  // otherwise this visitor plays the bank puzzle and the pin still settles for the day.
  const raced = await awaitPin(key, 6000);
  return raced || bank;
}
const getSplit = (ds) => resolveDaily('split', ds);
const getRiddle = (ds) => resolveDaily('riddle', ds);

// ---------- rendering ----------
function escHtml(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }

